const form = flow.get("catalogForm") || {};

const dspurl = form.dsp_url;
const bpn_provider = form.provider_bnp;

msg.payload = {
  "@context": {
    "@vocab": "https://w3id.org/edc/v0.0.1/ns/"
  },
  "protocol": "dataspace-protocol-http",
  "counterPartyAddress": dspurl,
  "counterPartyId": bpn_provider,
  "querySpec": {
    "offset": 0,
    "limit": 50
  }
};

return msg;

const assetId = flow.get("selectedAssetId");
const index = flow.get("catalogIndex") || {};
const item = index[assetId] || {};
const flow1 = flow.get("catalogForm");
const bpn_provider = flow1.provider_bnp; 
const bpn_consumer = "BPNL000000003HN2";

msg.payload = {
  "@context": [
    "https://w3id.org/tractusx/policy/v1.0.0",
    "http://www.w3.org/ns/odrl.jsonld",
    {
      "@vocab": "https://w3id.org/edc/v0.0.1/ns/",
      "tx": "https://w3id.org/tractusx/v0.0.1/ns/"
    }
  ],
  "@type": "ContractRequest",
  "counterPartyAddress": item.providerEndpoint,
  "protocol": "dataspace-protocol-http",
  "policy": {
    "@id": item.offerId,
    "@type": "Offer",
    "assigner": bpn_provider,
    "permission": [
      {
        "action": "use",
        "constraint": {
          "leftOperand": "tx:BusinessPartnerNumber",
          "operator": "eq",
          "rightOperand": bpn_consumer
        }
      }
    ],
    "prohibition": [],
    "obligation": [],
    "target": assetId
  },
  "callbackAddresses": []
};

return msg;

const assetId = flow.get("selectedAssetId");

msg.payload = {
  "@context": {
    "@vocab": "https://w3id.org/edc/v0.0.1/ns/"
  },
  "@type": "QuerySpec",
  "filterExpression": [
    {
      "operandLeft": "assetId",
      "operator": "=",
      "operandRight": assetId
    }
  ]
};

return msg;

const key = (msg.topic ?? "").toString().trim();
if (!key) return null;

let val = msg.payload;

// trim strings
if (typeof val === "string") val = val.trim();

// optional: leere Strings als "nicht gesetzt" behandeln
if (val === "") val = undefined;

const form = flow.get("catalogForm") || {};
form[key] = val;

flow.set("catalogForm", form);
msg.form = form; // fürs Debuggen

return msg;

const catalog = msg.payload || {};
const datasets = catalog["dcat:dataset"] || [];

const uiRows = [];
const options = [];
const index = {};

function getEndpoint(ds) {
  const dists = ds["dcat:distribution"] || [];
  for (const d of dists) {
    const svc = d?.["dcat:accessService"];
    const url = svc?.["dcat:endpointUrl"] || svc?.["dcat:endpointURL"];
    if (url) return url;
  }
  return "";
}

for (const ds of datasets) {
  const assetId = ds["@id"] || ds["id"];
  const description = ds["description"] || "";
  const offerId = ds["odrl:hasPolicy"]?.["@id"] || "";
  const providerEndpoint = getEndpoint(ds);

  uiRows.push({ assetId, description });
  options.push({ label: assetId, value: assetId });

  index[assetId] = { assetId, description, offerId, providerEndpoint };
}

flow.set("catalogIndex", index);

// an ui-table
const msgTable = { payload: uiRows };

// an ui-dropdown (Dashboard 2.0): Optionen dynamisch setzen
const msgDropdown = {
  ui_update: {
    options: options   // [{label, value}, ...]
  }
  // optional: payload: options[0]?.value  // wenn du direkt das erste auswählen willst
};

return [msgTable, msgDropdown];

flow.set("selectedAssetId", msg.payload);
// Auch global ablegen, damit der "EDC Consumer HNI-02"-Tab (eigener flow-Kontext)
// weiss, welche Shell zuletzt bearbeitet wurde - fuer den Zuliefererdaten-Rueckweg.
global.set("selectedAssetId", msg.payload);
return msg;

const code = msg.statusCode;

if (code >= 200 && code < 300) {
  msg.payload = "Asset angefordert";
} else {
  msg.payload = "Fehlgeschlagen";
}

return msg;

// msg.payload ist ein Array von EndpointDataReferenceEntry-Objekten
msg.transferProcessId = msg.payload[0].transferProcessId;

// optional: als payload für den nächsten Schritt
msg.payload = msg.transferProcessId;

return msg;

let da = msg.payload;

// falls ret=txt
if (typeof da === "string") {
  da = JSON.parse(da);
}

msg.endpoint = da.endpoint;
msg.authorization = da.authorization;

// optional für den nächsten Schritt als payload bündeln:
msg.payload = {
  endpoint: msg.endpoint,
  authorization: msg.authorization
};

// WICHTIG: URL für den nächsten http request setzen
msg.url = msg.endpoint;

return msg;

// msg.payload enthält die Response (obj oder string)
flow.set("lastResponse", msg.payload);
return msg;

let data = flow.get("lastResponse");
let filename = flow.get("download_filename") || "response.json";

if (data == null) {
  msg.statusCode = 404;
  msg.payload = "No data available yet.";
  return msg;
}

// Wenn Objekt -> JSON String
if (typeof data !== "string") data = JSON.stringify(data, null, 2);

// Dateiname vereinfachen
filename = filename.toString().trim().replace(/[^a-zA-Z0-9._-]/g, "_");
if (!filename) filename = "response.json";
if (!filename.endsWith(".json")) filename += ".json";

msg.headers = {
  "Content-Type": "application/json; charset=utf-8",
  "Content-Disposition": `attachment; filename="${filename}"`
};

msg.payload = data;
return msg;

// Adressbuch 
const book = {
  "HNI-01":  { name:"HNI-01", bpn:"BPNL000000003HN1", dsp:"https://hni-01-dsp.c-27d7c36.kyma.ondemand.com/api/v1/dsp"},
  "HNI-02": { name:"HNI-02", bpn:"BPNL000000003HN2", dsp:"https://hni-02-dsp.c-27d7c36.kyma.ondemand.com/api/v1/dsp"},
  "Sonova": { name:"Sonova", bpn:"BPNL000000003PS2", dsp:"https://prostep-sonova-dsp.c-27d7c36.kyma.ondemand.com/api/v1/dsp"},  
  "BOS": { name:"BOS", bpn:"BPNL000000003LJ2", dsp:"https://prostep-bos-dsp.c-27d7c36.kyma.ondemand.com/api/v1/dsp"},  
  "Hadi-Plast": { name:"Hadi-Plast", bpn:"BPNL000000003PH1", dsp:"https://prostep-hadiplast-dsp.c-27d7c36.kyma.ondemand.com/api/v1/dsp"},  
};

// Dropdown-Optionen erzeugen (label = sichtbarer Name, value = ID)
msg.ui_update = msg.ui_update || {};
msg.ui_update.options = Object.entries(book).map(([id, e]) => ({
  label: e.name,
  value: id
}));

// Buch speichern für spätere Lookup-Nodes
global.set("addressbook", book);

return msg;

const id = (msg.payload ?? "").toString();
const book = global.get("addressbook") || {};
const e = book[id];
if (!e) return [null, null, null];

const msgBpn = { topic: "provider_bnp", payload: e.bpn };
const msgDsp = { topic: "dsp_url",      payload: e.dsp };

// Output 1: beide Messages nacheinander an Store form fields
// Output 2: nur BPN an BPN-input
// Output 3: nur DSP an DSP-input
return [
  [msgBpn, msgDsp],
  msgBpn,
  msgDsp
];

const form = flow.get("catalogForm") || {};
const bpn = form.provider_bnp || "UNKNOWN_BPN";
const book = global.get("addressbook") || {};

let bpName = bpn;
for (const k of Object.keys(book)) {
  if (book[k]?.bpn === bpn) { bpName = book[k].name; break; }
}

msg.edcMeta = {
  bpn,
  bpName,
  exchangeTs: new Date().toISOString()
};

return msg;

let p = msg.payload;

// Text -> JSON/XML erkennen
if (typeof p === "string") {
  const t = p.trim();
  if (t.startsWith("{") || t.startsWith("[")) {
    try { p = JSON.parse(t); } catch (e) {}
  } else if (t.startsWith("<")) {
    msg.edcAasXml = t;
    return msg;
  }
}

// Objektfälle
if (typeof p === "object" && p !== null) {
  // direkt
  if (p.environment || p.submodels || p.assetAdministrationShells) {
    msg.edcAasJson = p;
    return msg;
  }
  // verschachtelt
  if (p.data && typeof p.data === "object") {
    msg.edcAasJson = p.data;
    return msg;
  }
  if (typeof p.data === "string" && p.data.trim().startsWith("<")) {
    msg.edcAasXml = p.data.trim();
    return msg;
  }
}

node.error("Unbekanntes EDC-AAS-Format", msg);
return null;

const src = msg.edcAasJson;
if (!src) {
  node.error("Kein edcAasJson vorhanden", msg);
  return null;
}

const out = [];

function walk(el) {
  if (!el || typeof el !== "object") return;

  // AAS Property (vereinfacht, JSON-Varianten tolerant)
  if (el.modelType === "Property" || el.valueType !== undefined && el.idShort) {
    out.push({
      baseIdShort: String(el.idShort),
      value: el.value,
      valueType: el.valueType || "xs:string"
    });
  }

  // Rekursion durch typische Felder
  const keys = ["submodels","submodelElements","value","elements","statements","children"];
  for (const k of keys) {
    const v = el[k];
    if (Array.isArray(v)) v.forEach(walk);
    else if (v && typeof v === "object") walk(v);
  }

  // Generisch alle Objektfelder traversieren (Fallback)
  for (const [k,v] of Object.entries(el)) {
    if (keys.includes(k)) continue;
    if (Array.isArray(v)) v.forEach(x => { if (x && typeof x === "object") walk(x); });
    else if (v && typeof v === "object") walk(v);
  }
}

walk(src);

msg.incomingProps = out;
return msg;

function safeToken(s) {
  return String(s || "UNKNOWN")
    .replace(/[^a-zA-Z0-9_]/g, "_")
    .replace(/_+/g, "_")
    .replace(/^_+|_+$/g, "")
    .substring(0, 40) || "UNKNOWN";
}

function tsToken(iso) {
  const d = new Date(iso || Date.now());
  const p = (n)=>String(n).padStart(2,"0");
  return `${d.getUTCFullYear()}${p(d.getUTCMonth()+1)}${p(d.getUTCDate())}T${p(d.getUTCHours())}${p(d.getUTCMinutes())}${p(d.getUTCSeconds())}Z`;
}

// Die reale (unkodierte) Shell-ID der Original-Shell, an die das neue
// Zuliefererdaten-Submodell spaeter angehaengt werden soll - kommt idealerweise
// direkt aus der empfangenen AAS-Umgebung, sonst als Fallback aus der Asset-ID.
msg.targetShellId = (msg.edcAasJson && msg.edcAasJson.assetAdministrationShells && msg.edcAasJson.assetAdministrationShells[0] && msg.edcAasJson.assetAdministrationShells[0].id)
  || (flow.get("selectedAssetId") || "").replace(/^aas-shell-/, "");

// Ziel-AAS (Platzhalter, bis GET angebunden ist)
if (!msg.targetAas) {
  msg.targetAas = { mergedProperties: [] };
}
if (!Array.isArray(msg.targetAas.mergedProperties)) {
  msg.targetAas.mergedProperties = [];
}

const bpName = msg.edcMeta?.bpName || "UNKNOWN_BP";
const exchangeTs = msg.edcMeta?.exchangeTs || new Date().toISOString();
const suffix = `${safeToken(bpName)}_${tsToken(exchangeTs)}`;

const incoming = Array.isArray(msg.incomingProps) ? msg.incomingProps : [];
let inserted = 0;

function existsIdShort(arr, idShort) {
  return arr.some(p => p.idShort === idShort);
}

for (const p of incoming) {
  const base = safeToken(p.baseIdShort || "unknown_property");
  let idShort = `${base}_${suffix}`;
  let i = 1;
  while (existsIdShort(msg.targetAas.mergedProperties, idShort)) {
    idShort = `${base}_${suffix}_${i++}`;
  }

  msg.targetAas.mergedProperties.push({
    idShort,
    value: p.value,
    valueType: p.valueType || "xs:string",
    sourceBpn: msg.edcMeta?.bpn || "UNKNOWN_BPN",
    sourceBpName: bpName,
    exchangeTs
  });

  inserted++;
}

msg.mergeResult = {
  inserted,
  bpName,
  exchangeTs
};

msg.mergedAas = msg.targetAas;
return msg;

const shellId = msg.targetShellId;
if (!shellId) {
    node.error("Kein targetShellId ermittelt - Zuliefererdaten-Upload uebersprungen", msg);
    return null;
}

const props = (msg.mergedAas && msg.mergedAas.mergedProperties) || [];
const submodelId = shellId + "/Zuliefererdaten";

msg.zuliefererSubmodel = {
    idShort: "Zuliefererdaten",
    id: submodelId,
    modelType: "Submodel",
    submodelElements: props.map(function (p) {
        return {
            idShort: p.idShort,
            modelType: "Property",
            valueType: p.valueType || "xs:string",
            value: (p.value === undefined || p.value === null) ? "" : String(p.value)
        };
    })
};

return msg;

const baseUrl = env.get("BASYX_BASE_URL") || env.get("SDI_AAS_URL") || "http://127.0.0.1:8081";
msg.url = baseUrl.replace(/\/$/, "") + "/submodels";
msg.headers = { "Content-Type": "application/json" };
msg.payload = msg.zuliefererSubmodel;
return msg;

const status = msg.statusCode;
if (status && (status < 200 || status >= 300) && status !== 409) {
    node.error("Submodel-POST fehlgeschlagen (HTTP " + status + "): " + JSON.stringify(msg.payload), msg);
    return null;
}

const baseUrl = env.get("BASYX_BASE_URL") || env.get("SDI_AAS_URL") || "http://127.0.0.1:8081";
const shellId = msg.targetShellId;
const encodedShellId = Buffer.from(shellId).toString("base64url");

msg.url = baseUrl.replace(/\/$/, "") + "/shells/" + encodedShellId + "/submodel-refs";
msg.headers = { "Content-Type": "application/json" };
msg.payload = {
    type: "ModelReference",
    keys: [{ type: "Submodel", value: msg.zuliefererSubmodel.id }]
};
return msg;

const status = msg.statusCode;
if (status && (status < 200 || status >= 300) && status !== 409) {
    node.error("Submodel-Ref-POST fehlgeschlagen (HTTP " + status + "): " + JSON.stringify(msg.payload), msg);
    return null;
}

node.warn("Zuliefererdaten-Submodell lokal angelegt: " + msg.zuliefererSubmodel.id);
return msg;

(async function () {
    const { S3Client, PutObjectCommand } = awsS3Sdk;

    function postJson(urlStr, headers, bodyObj) {
        return new Promise((resolve, reject) => {
            const u = new urlModule.URL(urlStr);
            const lib = u.protocol === "http:" ? httpModule : httpsModule;
            const bodyStr = JSON.stringify(bodyObj);
            const req = lib.request(u, {
                method: "POST",
                headers: Object.assign({ "Content-Length": Buffer.byteLength(bodyStr) }, headers)
            }, (res) => {
                let data = "";
                res.on("data", (chunk) => { data += chunk; });
                res.on("end", () => {
                    resolve({ status: res.statusCode, ok: res.statusCode >= 200 && res.statusCode < 300, body: data });
                });
            });
            req.on("error", reject);
            req.write(bodyStr);
            req.end();
        });
    }

    function getJson(urlStr, headers) {
        return new Promise((resolve, reject) => {
            const u = new urlModule.URL(urlStr);
            const lib = u.protocol === "http:" ? httpModule : httpsModule;
            const req = lib.request(u, { method: "GET", headers }, (res) => {
                let data = "";
                res.on("data", (chunk) => { data += chunk; });
                res.on("end", () => {
                    resolve({ status: res.statusCode, ok: res.statusCode >= 200 && res.statusCode < 300, body: data });
                });
            });
            req.on("error", reject);
            req.end();
        });
    }

    const bucket = (env.get("S3_BUCKET") || env.get("SDI_S3_BUCKET"));
    const region = (env.get("S3_REGION") || env.get("SDI_S3_REGION")) || "auto";
    const endpoint = (env.get("S3_ENDPOINT") || env.get("SDI_S3_ENDPOINT"));
    const publicBaseUrl = (env.get("S3_PUBLIC_BASE_URL") || env.get("SDI_S3_PUBLIC_URL"));
    const accessKeyId = (env.get("AWS_ACCESS_KEY_ID") || env.get("SDI_S3_ACCESS_KEY_ID"));
    const secretAccessKey = (env.get("AWS_SECRET_ACCESS_KEY") || env.get("SDI_S3_SECRET_ACCESS_KEY"));
    const edcManagementUrl = (env.get("EDC_MANAGEMENT_URL_HNI02") || env.get("SDI_EDC_PARTNER_MANAGEMENT_URL"));
    const edcApiKey = (env.get("EDC_API_KEY_HNI02") || env.get("SDI_EDC_PARTNER_API_KEY"));
    const accessPolicyId = (env.get("EDC_ACCESS_POLICY_ID_HNI02") || env.get("SDI_EDC_ACCESS_POLICY_ID"));
    const contractPolicyId = (env.get("EDC_CONTRACT_POLICY_ID_HNI02") || env.get("SDI_EDC_CONTRACT_POLICY_ID"));

    if (!bucket || !publicBaseUrl || !accessKeyId || !secretAccessKey) {
        throw new Error("S3_BUCKET / S3_PUBLIC_BASE_URL / AWS_ACCESS_KEY_ID / AWS_SECRET_ACCESS_KEY fehlen auf diesem Tab");
    }

    const shellId = msg.targetShellId;
    const shellName = String(shellId).split("/").filter(Boolean).pop().replace(/[^A-Za-z0-9._-]/g, "_");
    const objectKey = "zuliefererdaten/" + shellName + ".json";
    const assetId = "zuliefererdaten-" + shellName;
    const contractDefId = "zuliefererdaten-contractdef-" + shellName;

    const envDoc = {
        assetAdministrationShells: [],
        submodels: [msg.zuliefererSubmodel],
        conceptDescriptions: []
    };

    const s3ClientConfig = { region, credentials: { accessKeyId, secretAccessKey } };
    if (endpoint) {
        s3ClientConfig.endpoint = endpoint;
        s3ClientConfig.forcePathStyle = true;
    }
    const s3 = new S3Client(s3ClientConfig);
    await s3.send(new PutObjectCommand({
        Bucket: bucket,
        Key: objectKey,
        Body: JSON.stringify(envDoc),
        ContentType: "application/json"
    }));

    msg.zuliefererObjectKey = objectKey;
    msg.zuliefererPublicUrl = publicBaseUrl.replace(/\/$/, "") + "/" + objectKey;

    if (!edcManagementUrl || !edcApiKey || !accessPolicyId || !contractPolicyId) {
        node.warn("EDC_*_HNI02 Env-Vars nicht vollstaendig gesetzt - Zuliefererdaten nur in Bucket hochgeladen, kein EDC-Offer registriert");
        msg.payload = { status: "ok", objectKey, edcOfferRegistered: false };
        node.send(msg);
        node.done();
        return;
    }

    const edcHeaders = { "Content-Type": "application/json", "X-Api-Key": edcApiKey };

    const existingAsset = await getJson(edcManagementUrl + "/v3/assets/" + encodeURIComponent(assetId), edcHeaders);
    if (!existingAsset.ok) {
        const assetBody = {
            "@context": {},
            "@type": "Asset",
            "@id": assetId,
            properties: {
                name: "Zuliefererdaten " + shellId,
                description: "Zuliefererdaten " + shellId
            },
            dataAddress: {
                "@type": "DataAddress",
                type: "HttpData",
                baseUrl: msg.zuliefererPublicUrl
            }
        };
        const assetRes = await postJson(edcManagementUrl + "/v3/assets", edcHeaders, assetBody);
        if (!assetRes.ok && assetRes.status !== 409) {
            throw new Error("Asset creation failed: " + assetRes.status + " " + assetRes.body);
        }
    }

    const existingCd = await getJson(edcManagementUrl + "/v3/contractdefinitions/" + encodeURIComponent(contractDefId), edcHeaders);
    if (!existingCd.ok) {
        const contractDefBody = {
            "@context": {},
            "@type": "ContractDefinition",
            "@id": contractDefId,
            accessPolicyId: accessPolicyId,
            contractPolicyId: contractPolicyId,
            assetsSelector: {
                "@type": "CriterionDto",
                operandLeft: "https://w3id.org/edc/v0.0.1/ns/id",
                operator: "=",
                operandRight: assetId
            }
        };
        const cdRes = await postJson(edcManagementUrl + "/v3/contractdefinitions", edcHeaders, contractDefBody);
        if (!cdRes.ok && cdRes.status !== 409) {
            throw new Error("ContractDefinition creation failed: " + cdRes.status + " " + cdRes.body);
        }
    }

    msg.payload = { status: "ok", assetId, objectKey, contractDefinitionId: contractDefId, edcOfferRegistered: true };
    node.send(msg);
    node.done();
})().catch(err => {
    node.error(err, msg);
});
return null;

const baseUrl = env.get("BASYX_BASE_URL") || env.get("SDI_AAS_URL") || "http://127.0.0.1:8081";
msg.url = baseUrl.replace(/\/$/, "") + "/shells?limit=200";
return msg;

const data = msg.payload;
const shells = Array.isArray(data) ? data : (data && data.result) || [];

const options = shells
    .filter(s => s && typeof s.id === "string")
    .map(s => ({ label: (s.idShort || s.id), value: s.id }));

msg.ui_update = { options };
msg.payload = "Shells geladen: " + options.length;
return msg;

const key = (msg.topic ?? "").toString().trim();
if (!key) return null;

let val = msg.payload;
if (typeof val === "string") val = val.trim();
if (val === "") val = undefined;

const form = flow.get("publishShellForm") || {};
form[key] = val;
flow.set("publishShellForm", form);

return null;

const form = flow.get("publishShellForm") || {};
const shellId = form.shell_id;

if (!shellId) {
    msg.payload = "Bitte zuerst eine Shell-ID eingeben.";
    return [null, msg];
}

const baseUrl = (env.get("PUBLISH_BASE_URL") || env.get("SDI_NODERED_URL")) || "http://127.0.0.1:1880";
const apiKey = (env.get("BACKEND_API_KEY") || env.get("SDI_EDC_BACKEND_KEY"));
if (!apiKey) {
    msg.payload = "BACKEND_API_KEY ist auf diesem Tab nicht gesetzt.";
    return [null, msg];
}

const encodedId = Buffer.from(shellId).toString("base64url");
msg.url = baseUrl.replace(/\/$/, "") + "/dsp-backend/shells/" + encodedId + "/publish";
msg.headers = { "x-api-key": apiKey };

const statusMsg = { payload: "\u23F3 Ver\u00f6ffentliche \"" + shellId + "\" ..." };
return [msg, statusMsg];

const status = msg.statusCode;
let body = msg.payload;
try { if (typeof body === "string") body = JSON.parse(body); } catch (e) { /* ignore */ }

if (status >= 200 && status < 300 && body && body.status === "ok") {
    const edcNote = body.edcOfferRegistered ? " (EDC-Offer registriert)" : " (EDC-Offer noch nicht registriert - EDC-Env-Vars pr\u00fcfen)";
    msg.payload = "\u2705 Erfolgreich ver\u00f6ffentlicht: " + body.objectKey + edcNote;
} else {
    const errMsg = (body && body.error) ? body.error : (typeof msg.payload === "string" ? msg.payload : JSON.stringify(msg.payload));
    msg.payload = "\u274C Fehler (HTTP " + status + "): " + errMsg;
}

return msg;

const form = flow.get("assetForm") || {};

const assetId = form.asset_id;
const description = form.description;
const baseUrl = form.url_asset;
const dataType = form.data_type || "HttpData";

const missing = [];
if (!assetId) missing.push("Asset-ID");
if (!description) missing.push("Description");
if (!baseUrl) missing.push("Asset-URL");

if (missing.length) {
  // Status an UI
  const uiMsg = { payload: `Bitte ausfüllen: ${missing.join(", ")}` };
  return [null, uiMsg];
}

// request body
msg.payload = {
  "@context": {},
  "@type": "Asset",
  "@id": assetId,
  "properties": { "description": description },
  "dataAddress": {
    "@type": "DataAddress",
    "type": dataType,
    "baseUrl": baseUrl
  }
};

